import{_ as e,o as a,c as n,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Tentar de novo documento não encontrado","description":"","frontmatter":{"title":"Tentar de novo documento não encontrado","id":"eproc-recarregar-documento-nao-encontrado","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-recarregar-documento-nao-encontrado"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-recarregar-documento-nao-encontrado"}],["meta",{"property":"og:title","content":"Tentar de novo documento não encontrado | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-recarregar-documento-nao-encontrado.md","filePath":"funcionalidades/eproc-recarregar-documento-nao-encontrado.md"}'),t={name:"funcionalidades/eproc-recarregar-documento-nao-encontrado.md"};function c(d,o,s,i,u,p){return a(),n("div",null,o[0]||(o[0]=[r('<h1 id="tentar-de-novo-documento-nao-encontrado" tabindex="-1">Tentar de novo documento não encontrado <a class="header-anchor" href="#tentar-de-novo-documento-nao-encontrado" aria-label="Permalink to &quot;Tentar de novo documento não encontrado&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Às vezes, ao abrir um documento, o eproc responde &quot;Erro acessar o documento: Documento não encontrado.&quot; em vez de mostrar a peça. O erro é passageiro, comum em processos migrados do PJe, e costuma sumir ao recarregar a página. Com este recurso, o eploc recarrega sozinho, até 3 vezes seguidas.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, na janela de documento aberta pela tabela de eventos, inclusive na pré-visualização da página do processo.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um documento normalmente.</li><li>Se o eproc responder &quot;Documento não encontrado&quot;, um aviso do eploc aparece no topo da janela, como &quot;Documento não encontrado. Tentando de novo (1 de 3)…&quot;, e a página é recarregada em um segundo.</li><li>Na maioria das vezes, o documento abre numa dessas tentativas.</li><li>Se o erro continuar depois da terceira, o aviso diz que o documento continua não encontrado e oferece o botão <strong>Tentar de novo</strong>, que recomeça as tentativas.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>As tentativas são contadas por documento e zeram depois de meio minuto sem erro, então abrir o mesmo documento mais tarde volta a ter as 3 tentativas automáticas.</p><p>Só a janela do documento é recarregada, nunca a página do processo.</p><p>Se o documento realmente não existir mais, as tentativas não resolvem: o erro continua e o aviso fica com o botão de tentar de novo.</p>',13)]))}const h=e(t,[["render",c]]);export{m as __pageData,h as default};
